def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find connected colored regions, treating embedded 2s as part of the region.
    seen = set()
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 3 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            regions.append(cells)

    for cells in regions:
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 2 and rmin <= r <= rmax and cmin <= c <= cmax:
                    for rr in range(max(0, r-1), min(h, r+2)):
                        for cc in range(max(0, c-1), min(w, c+2)):
                            if grid[rr][cc] == 3:
                                out[rr][cc] = 1
    return out
